import{z as o,x as n,o as i,c as s,q as t,j as r,D as e,d as p,s as P,S as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"SPPO Self-Play PO","description":"","frontmatter":{"title":"SPPO Self-Play PO","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sppo.md","filePath":"llm/sppo.md","lastUpdated":1791063341000}'),B={name:"llm/sppo.md"};function A(d,a,m,h,c,O){const l=n("Mermaid");return i(),s("div",null,[a[2]||(a[2]=t('<h1 id="sppo-self-play-po" tabindex="-1">SPPO Self-Play PO <a class="header-anchor" href="#sppo-self-play-po" aria-label="Permalink to &quot;SPPO Self-Play PO&quot;">​</a></h1><div class="epigraph"><p>偏好不必能写成一个可传递的标量奖励；把它当成两人常和博弈，用自我对弈去逼近纳什均衡，策略就按对当前自己的胜率做乘性更新。</p><footer>—— Wu 等，Self-Play Preference Optimization for Language Model Alignment，2024</footer></div><p>Bradley–Terry 给每条回答一个分数，胜率由分数差的 logistic 决定。人的比较可以循环、可以不传递，一个标量无法表示。Munos、Swamy、Wang 等人把 RLHF 改写成两人常和博弈：策略 \\(\\pi\\) 的收益是它对对手策略的期望胜率，目标是纳什均衡（von Neumann winner）。Wu 等人给出一个能接到大模型微调上的实现：Self-Play Preference Optimization（SPPO）。每轮用当前策略采样、用偏好神谕给组内胜率，再把「相对上一轮的对数比」平方回归到「对经验策略的超额胜率」。它与 <a href="/llm/dpo">DPO</a> 的成对 logistic 不同：监督是一条回答相对一整组对手的平均胜率，不是一对 \\((y_w,y_l)\\) 的符号。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标准 RLHF 先拟合 BT 奖励再 <a href="/llm/ppo-llm">PPO</a>，或把奖励回代成 DPO。两条路都假定偏好由潜在分数生成。一旦 \\(A\\succ B\\)、\\(B\\succ C\\)、\\(C\\succ A\\)，不存在与数据一致的 \\(r\\)。IPO 改的是 \\(\\Psi\\) 映射，仍在成对概率上工作；它最大化的是相对某个参考策略的期望胜率，不是博弈均衡。参考一过时，目标就不再是「对任何对手都不差」。</p><p><span class="marginnote">「非传递偏好」翻译成大白话：人可能觉得 A 比 B 好、B 比 C 好，到了 C 对 A 却又翻盘——考虑场景时这很常见。这种循环排序在数学上塞不进「每条回答一个分数、分高者赢」的模型，这正是要换用博弈表述的根本原因。</span></p><p>博弈表述的目标明确：找 \\(\\pi^*\\) 使得 \\(\\mathbb{P}(\\pi^*\\succ\\pi)\\ge 1/2\\) 对一切 \\(\\pi\\) 成立（对称纳什）。Freund 与 Schapire 的乘性权重给出平均策略以 \\(O(1/\\sqrt{T})\\) 收敛到均衡的对偶间隙。困难是把指数更新</p> \\[\\pi_{t+1}(y\\mid x)\\propto \\pi_t(y\\mid x)\\exp\\bigl(\\eta\\,\\mathbb{P}(y\\succ\\pi_t\\mid x)\\bigr) \\]<p>写成可对神经网络求梯度的损失，并且用有限次偏好查询估计 \\(\\mathbb{P}(y\\succ\\pi_t)\\)。Swamy 等人的 SPO 在理论上落到 Hedge，实践上建议再用 PPO 或 SAC 去近似指数更新；SPPO 要的是直接可微、可大规模微调的平方损失，而不是再套一层策略梯度。</p><h3 id="成对对称损失推的是间隔-不是密度" tabindex="-1">成对对称损失推的是间隔，不是密度 <a class="header-anchor" href="#成对对称损失推的是间隔-不是密度" aria-label="Permalink to &quot;成对对称损失推的是间隔，不是密度&quot;">​</a></h3><p>DPO / <a href="/llm/ipo">IPO</a> 在一对回答上做对称对比，配分函数相减消掉。梯度保证相对对数比变大，不保证受欢迎回答的绝对似然上升——Pal 等人指出过这一现象。纳什更新需要的是：一条 \\(y\\) 若对当前策略的平均胜率高于 \\(1/2\\)，其概率质量应上升，平局则不动。这是相对「对手策略」的绝对校准，不是相对另一条样本的差。</p><p><span class="marginnote">论文中的 SPPO 与 Swamy 等的 SPO 不是同一算法。SPO 是一般约化框架；SPPO 专指接在 LLM 上、用平方损失近似指数更新的那一套。后起的「Sequence-Level PPO」也有人叫 SPPO，与本篇无关。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对固定提示，指数更新等价于</p> \\[\\log\\frac{\\pi_{t+1}(y\\mid x)}{\\pi_t(y\\mid x)}=\\eta\\,\\mathbb{P}(y\\succ\\pi_t\\mid x)-\\log Z_{\\pi_t}(x). \\]<p>SPPO 不靠成对相减消 \\(Z\\)，而直接对这一等式做 \\(L_2\\) 拟合。有限样本时，对每个 \\(x\\) 从 \\(\\pi_t\\) 采 \\(K\\) 条，用经验策略 \\(\\widehat{\\pi}_t^K\\) 估计胜率。实践中把 \\(\\log Z\\) 换成常数 \\(\\eta/2\\)（在胜负近似均匀、 \\(K\\to\\infty\\) 时 \\(Z\\to e^{\\eta/2}\\)），得到论文里实际最小化的目标：</p> \\[\\mathbb{E}_{y\\sim\\pi_t}\\Bigl(\\log\\frac{\\pi(y\\mid x)}{\\pi_t(y\\mid x)}-\\eta\\bigl(\\mathbb{P}(y\\succ\\widehat{\\pi}_t^K\\mid x)-\\tfrac12\\bigr)\\Bigr)^2. \\]<p>平局（胜率 \\(1/2\\)）时对数比目标为零；高于 \\(1/2\\) 则提高密度。算法每轮：采样 \\(K\\) 条、查询偏好神谕得到组内两两胜率、构造 \\((x,y,\\hat P)\\)、按上式更新到 \\(\\pi_{t+1}\\)。作者实验用 UltraFeedback 的约 60k 条提示（不要原回答），偏好神谕是 0.4B 的 PairRM，不引入 GPT-4 写的回答或偏好。从 Mistral-7B-Instruct-v0.2 出发，AlpacaEval 2.0 对 GPT-4-Turbo 的长度控制胜率报到 28.53%；从 Llama-3-8B-Instruct 出发报到 38.77%。这些是该设置下的数字，不是泛化保证。</p><p><span class="marginnote">数字算一笔账：\\(K=5\\) 时每个提示要生成 5 条候选、做 \\(\\binom{5}{2}=10\\) 次成对比较；一轮 60k 提示就是 60 万次 PairRM 前向。神谕虽只有 0.4B，这笔开销与生成同一量级，\\(K\\) 的取值本质上是预算决策。</span></p>',19)),(i(),r(E,null,{default:e(()=>[P(l,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20PI%5B%22%E5%BD%93%E5%89%8D%20%CF%80t%22%5D%20--%3E%20S%5B%22%E6%AF%8F%E6%8F%90%E7%A4%BA%E9%87%87%20K%20%E6%9D%A1%22%5D%0A%20%20S%20--%3E%20P%5B%22%E5%81%8F%E5%A5%BD%E7%A5%9E%E8%B0%95%EF%BC%9A%E7%BB%84%E5%86%85%E8%83%9C%E7%8E%87%22%5D%0A%20%20P%20--%3E%20W%5B%22%C5%B7%20%E7%9B%B8%E5%AF%B9%E7%BB%8F%E9%AA%8C%E7%AD%96%E7%95%A5%E7%9A%84%E5%B9%B3%E5%9D%87%E8%83%9C%E7%8E%87%22%5D%0A%20%20W%20--%3E%20SQ%5B%22%E5%B9%B3%E6%96%B9%E6%8D%9F%E5%A4%B1%EF%BC%9Alog(%CF%80%2F%CF%80t)%20%E2%89%88%20%CE%B7(P%CC%82%20%E2%88%92%201%2F2)%22%5D%0A%20%20SQ%20--%3E%20N%5B%22%CF%80t%2B1%22%5D%0A%20%20N%20--%3E%20PI%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h3 id="与-dpo、ipo、dno-的接口" tabindex="-1">与 DPO、IPO、DNO 的接口 <a class="header-anchor" href="#与-dpo、ipo、dno-的接口" aria-label="Permalink to &quot;与 DPO、IPO、DNO 的接口&quot;">​</a></h3><p>DPO 吃离线 \\((y_w,y_l)\\)，一次更新，参考冻结。SPPO 是迭代自我对弈：参考是上一轮 \\(\\pi_t\\)，标签是对当前自己的胜率，不必预先存在人类成对。IPO 的平方损失打在成对对数比差上，目标间隔常数；SPPO 的平方损失打在单条对数比上，目标是超额胜率。并发的 Direct Nash Optimization 用交叉熵拟合胜率差，实践实现仍常退回迭代 DPO；SPPO 实验里坚持自己的平方目标，并且不用更强模型的外部监督。REBEL 在偏好设定下与 SPPO 相近，差别主要在是否对绝对胜率回归还是对相对奖励回归。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="乘性权重为何收敛到均衡" tabindex="-1">乘性权重为何收敛到均衡 <a class="header-anchor" href="#乘性权重为何收敛到均衡" aria-label="Permalink to &quot;乘性权重为何收敛到均衡&quot;">​</a></h3><p>两人常和博弈里，乘性权重是无悔算法：平均策略的对偶间隙以 \\(O(1/\\sqrt{T})\\) 下降（Freund &amp; Schapire 1999；论文 Theorem 4.1 在可实现假设下复述）。每步把质量乘上 \\(\\exp(\\eta\\times\\text{对当前对手的收益})\\)，对手若是上一轮的自己，就是自我对弈。平方损失是对「理想对数比」的投影：若函数类够大且优化够准，一步接近指数更新；函数类不够时，只是在对数概率空间里做有偏近似。理论保证的是平均策略 \\(\\bar\\pi_T\\)，实践部署的是最后一轮 \\(\\pi_T\\)，两者不必相同。论文没有声称最后一轮就是精确纳什。</p><p>胜率估计来自 \\(K\\) 条样本的两两比较，查询次数 \\(O(K^2)\\)。\\(K\\) 太小，经验对手覆盖不足，超额胜率噪声大，平方回归会把噪声写进策略。PairRM 是近似神谕，不是人类 \\(\\mathbb{P}\\)；均衡是相对这个神谕的均衡。神谕有长度偏置，纳什策略也会学长度偏置——作者因此在 AlpacaEval 上报告长度控制胜率。</p><p><span class="marginnote">SPPO 的「无外部监督」指实验不拿 GPT-4 写回答、不当裁判；不是没有偏好信号。PairRM 仍是外部模型。换成自己训的成对 RM，均衡就相对那个 RM，与 InstructGPT 的数据面相同。</span></p><h3 id="平方损失与策略梯度的近亲关系" tabindex="-1">平方损失与策略梯度的近亲关系 <a class="header-anchor" href="#平方损失与策略梯度的近亲关系" aria-label="Permalink to &quot;平方损失与策略梯度的近亲关系&quot;">​</a></h3><p>把 \\(\\log(\\pi/\\pi_t)\\) 回归到优势形状的目标，梯度含 \\(\\nabla\\log\\pi\\) 乘残差，形式上接近带基线的策略梯度，只是样本来自本轮开始时冻结的 \\(\\pi_t\\)，而不是每一步都在线采样。作者称之为半在线：一轮内多步 SGD 复用同一批合成数据，轮与轮之间才重新生成。这解释了为何它能提高赢家似然、压低输家似然，而不只拉开相对间隔。代价是每轮都要生成 \\(K\\) 条并打两两比较，比纯离线 DPO 贵，比 PPO 四模型栈仍简单——没有价值网络，偏好神谕可以远小于策略。</p>',9)),(i(),r(E,null,{default:e(()=>[P(l,{id:"mermaid-77",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20DP%5B%22DPO%EF%BC%9A%E6%88%90%E5%AF%B9%E7%9B%91%E7%9D%A3%22%5D%0A%20%20%20%20A%5B%22%E4%B8%80%E5%AF%B9%20(y_w%2C%20y_l)%22%5D%20--%3E%20B%5B%22%E5%8F%AA%E6%8B%89%E5%BC%80%E7%9B%B8%E5%AF%B9%E9%97%B4%E9%9A%94%EF%BC%9A%E8%B5%A2%E5%AE%B6%E4%BC%BC%E7%84%B6%E6%9C%AA%E5%BF%85%E4%B8%8A%E5%8D%87%22%5D%0A%20%20end%0A%20%20subgraph%20SP%5B%22SPPO%EF%BC%9A%E7%BB%84%E5%86%85%E8%87%AA%E6%88%91%E5%AF%B9%E5%BC%88%22%5D%0A%20%20%20%20C%5B%22%E6%AF%8F%E6%8F%90%E7%A4%BA%E9%87%87%20K%20%E6%9D%A1%E5%80%99%E9%80%89%22%5D%20--%3E%20D%5B%22%E7%A5%9E%E8%B0%95%E6%89%93%E4%B8%A4%E4%B8%A4%E8%83%9C%E7%8E%87%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22%E7%AE%97%20y%20%E7%9B%B8%E5%AF%B9%E7%BB%8F%E9%AA%8C%E7%AD%96%E7%95%A5%E7%9A%84%E5%B9%B3%E5%9D%87%E8%83%9C%E7%8E%87%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22P%20%E5%A4%A7%E4%BA%8E%201%2F2%20%E6%8F%90%E5%AF%86%E5%BA%A6%EF%BC%9B%E5%B0%8F%E4%BA%8E%E9%99%8D%EF%BC%9B%E7%AD%89%E4%BA%8E%E4%B8%8D%E5%8A%A8%22%5D%0A%20%20end%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[p(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">常见误区：以为「自我对弈」就是模型给自己打分、难免自嗨。打分的是独立的成对偏好神谕（如 PairRM），不是策略本身；策略只负责采样候选与更新参数。真正会「自嗨」的情形，是神谕被换成被优化的模型自己。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>SPPO 依赖可查询的成对偏好神谕和可负担的组采样。神谕若只是 BT 奖励模型，博弈表述的「能表示非传递」在实现上会退化为近似传递。提示集质量决定自我对弈能探索的区域：只用 60k UltraFeedback 提示，均衡是这些提示上的均衡，换域不会自动好。迭代轮数与 \\(\\eta\\) 决定走多近；\\(\\eta\\) 过大，平方目标要求的对数比一步跳太远，语言模型拟合不良。</p><p>不要把 SPPO 写成「迭代 DPO」。数据构造可以看起来像组内排序，损失却不是 logistic 差。也与后来同名的序列级 PPO 无关。并发的 Nash 学习工作（NLHF、DNO）共享博弈目标，实现与监督来源不同；比较时应看是否用更强模型当金标，而不是看名字里有没有 Nash。</p><p><span class="marginnote">组内两两比较的计算是 \\(K^2\\) 次神谕前向。\\(K=4\\) 还好，\\(K=16\\) 就已经和生成成本一个量级。论文可以选子集进 \\(\\mathcal{D}_t\\)；只留极端胜负会回到成对方法，理论与「对经验策略的平均胜率」不再一致。</span></p><h3 id="何时不必上-sppo" tabindex="-1">何时不必上 SPPO <a class="header-anchor" href="#何时不必上-sppo" aria-label="Permalink to &quot;何时不必上 SPPO&quot;">​</a></h3><p>已有干净成对人类数据、且 BT 近似够用时，离线 DPO / IPO 更便宜。奖励可验证、同一题可打标量分时，组相对策略梯度（<a href="/llm/grpo">GRPO</a>、<a href="/llm/rloo">RLOO</a>）更直接，不必构造胜率矩阵。没有可靠偏好神谕、又不能在线采样时，SPPO 无法启动。非传递性若从未在数据里出现，为它付组采样预算没有收益。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SPPO 把对齐写成两人常和博弈，用自我对弈近似纳什均衡，而不是拟合可传递的标量奖励。</li><li>每轮对当前策略采样，用偏好神谕估计相对经验策略的胜率，平方回归对数比到 \\(\\eta(\\hat P-1/2)\\)。</li><li>相对 DPO/IPO，监督是单条回答的绝对超额胜率，配分函数不靠成对相减消去。</li><li>理论保证的是平均策略的对偶间隙；实践部署最后一轮，神谕误差会进入均衡。</li><li>实验用 PairRM 与 UltraFeedback 提示，不依赖 GPT-4 写样本；数字绑定该设置。</li><li>同名的 SPO 或序列级 PPO 不是这篇算法。</li><li>出处：Wu, Sun, Yuan, Ji, Yang, Gu，<em>Self-Play Preference Optimization for Language Model Alignment</em>，arXiv:2405.00675，2024。</li></ul>',9))])}const S=o(B,[["render",A]]);export{u as __pageData,S as default};
